2	export class FakeClock {
3	  #now = 0;
4	  #id = 0;
5	  #timers = new Map();
6	
7	  now() {
8	    return this.#now;
9	  }
10	
11	  setTimeout(fn, ms) {
12	    const id = ++this.#id;
13	    this.#timers.set(id, { at: this.#now + ms, fn, id });
14	    return id;
15	  }
16	
17	  clearTimeout(id) {
18	    this.#timers.delete(id);
19	  }
20	
21	  get pending() {
22	    return this.#timers.size;
23	  }
24	
25	  /** Moves time forward, firing due timers in (time, creation) order, including timers they create. */
26	  advance(ms) {
27	    const target = this.#now + ms;
28	    for (;;) {
29	      const due = [...this.#timers.values()].filter((t) => t.at <= target).sort((a, b) => a.at - b.at || a.id - b.id)[0];
30	      if (!due) break;
31	      this.#timers.delete(due.id);
32	      this.#now = Math.max(this.#now, due.at);
33	      due.fn();
34	    }
35	    this.#now = target;
36	  }
37	}
