42	/** A job function whose attempts are completed by hand. Every call is appended to `log` as `name#attempt`. */
43	export function job(log, name) {
44	  const j = { name, ctxs: [], pending: [] };
45	  j.fn = (ctx) => {
46	    log.push(`${name}#${ctx.attempt}`);
47	    j.ctxs.push(ctx);
48	    let resolve;
49	    let reject;
50	    const promise = new Promise((res, rej) => ((resolve = res), (reject = rej)));
51	    j.pending.push({ resolve, reject });
52	    return promise;
53	  };
54	  j.ok = (value) => j.pending.shift().resolve(value);
55	  j.fail = (error) => j.pending.shift().reject(error);
56	  return j;
57	}
