59	/** Observes a promise without leaving an unhandled rejection. */
60	export function track(promise) {
61	  const t = { state: 'pending', value: undefined };
62	  promise.then(
63	    (value) => Object.assign(t, { state: 'ok', value }),
64	    (value) => Object.assign(t, { state: 'err', value }),
65	  );
66	  return t;
67	}

