{"path": "src/pqueue.js", "content": "/**
 * Stable priority queue. Higher `priority` comes out first; entries with equal priority come out in the
 * order of their `seq` (lower first). `seq` is chosen by the caller, so an entry that is pushed again later
 * with its old `seq` goes back in front of entries that were queued after it.
 *
 *   push(item, priority, seq)       add an entry
 *   takeFirst(accept)               remove and return the first item (in queue order) for which
 *                                   accept(item) is true, or undefined when there is none
 *   remove(item)                    remove that item; returns true when it was queued
 *   size                            number of queued entries
 */
export class PriorityQueue {
  #entries = [];

  push(item, priority, seq) {
    const entry = { item, priority, seq };
    let i = this.#entries.length;
    while (i > 0) {
      const prev = this.#entries[i - 1];
      if (prev.priority > priority || (prev.priority === priority && prev.seq < seq)) break;
      i--;
    }
    this.#entries.splice(i, 0, entry);
  }

  takeFirst(accept) {
    for (let i = 0; i < this.#entries.length; i++) {
      if (accept(this.#entries[i].item)) {
        return this.#entries.splice(i, 1)[0].item;
      }
    }
    return undefined;
  }

  remove(item) {
    const i = this.#entries.findIndex((e) => e.item === item);
    if (i === -1) return false;
    this.#entries.splice(i, 1);
    return true;
  }

  get size() {
    return this.#entries.length;
  }
}
