      fn,
      key: opts.key,
      priority: opts.priority,
      retries: opts.retries,
      backoff: opts.backoff,
      shouldRetry: opts.shouldRetry,
      signal: opts.signal,
      attempt: 0,
      seq: ++this.#seq,
      state: 'queued',
      timer: null,
      cancelled: false,
      result,
    };
    if (opts.signal) {
